  store=new Store(new StorageService());await store.init();perf.mark('storage-ready');
  sync=new SyncService(store);await sync.init();perf.mark('sync-ready');
  nativeBridge=new NativeBridge();await nativeBridge.init();perf.mark('native-ready');
  platform=new PlatformService(store,sync);perf.mark('platform-ready');
  if(nativeBridge.capabilities.native)writeLocalText('parcelles:native-platform',nativeBridge.capabilities.platform||'ios');
  if(state().preferences.biometricLock&&nativeBridge.capabilities.native)await ensureNativeUnlocked({force:true});
  store.setWriteGuard(operation=>sync.canWriteEntity(operation.entity,operation.action));
  parcelMap=new ParcelMap({onSelect:parcel=>{selectedParcelId=parcel.id;rememberRecent(parcel.id);renderMapSheet();},onToast:toast});
  bindEvents();store.subscribe((data,event)=>{renderAfterStoreChange(data,event);scheduleAutomationEvent(event);});perf.mark('events-ready');
  applyTheme();renderAll();renderNetwork();perf.mark('first-render');
  requestPersistentStorage().catch(()=>false);
  registerAppServiceWorker({onUpdate:update=>toast('Une nouvelle version de Parcelles est prête.','success',{label:'Mettre à jour',run:update.activate})}).catch(error=>console.warn('[Parcelles] SW',error));
  window.addEventListener('online',()=>{renderNetwork();if(!weatherCache)refreshWeather({silent:true});backgroundSync();});
  window.addEventListener('offline',renderNetwork);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&fieldModeOpen){requestFieldWakeLock();updateFieldSessionClock();}});
  window.addEventListener('parcelles:native-state',event=>handleNativeState(event.detail||{}));
  window.addEventListener('parcelles:native-network',renderNetwork);
  window.addEventListener('parcelles:native-notification-action',event=>handleNativeNotificationAction(event.detail||{}));
  window.addEventListener('parcelles:deep-link',event=>handleNativeDeepLink(event.detail?.url||''));
  document.addEventListener('parcelles:gps',event=>{lastGps=event.detail;renderNetwork();if(fieldModeOpen)renderFieldGps(event.detail);});
  window.addEventListener('hashchange',applyHashRoute);window.addEventListener('popstate',applyHashRoute);
  applyHashRoute();
  idleTask(()=>navigator.onLine&&refreshWeather({silent:true}),{timeout:900});
  idleTask(maybeSystemNotificationDigest,{timeout:1700});
  idleTask(checkStoragePressure,{timeout:2300});
  setTimeout(maybeOnboarding,120);
