  for(const photo of photos){const blob=await store.storage.blobGet(photo.id);if(blob){const url=URL.createObjectURL(blob);urls.push(url);const button=document.createElement('button');button.className='photo-thumb';button.dataset.action='view-attachment';button.dataset.type='photos';button.dataset.id=photo.id;button.innerHTML=`<img src="${url}" alt="${escapeHtml(photo.note||photo.name||'Photo de parcelle')}">`;root.append(button);}}
  root.querySelector('.empty-state')?.remove();setTimeout(()=>urls.forEach(url=>URL.revokeObjectURL(url)),60000);
