  const form=$('#work-form');
  $('#work-template').onchange=()=>{const t=templates.find(x=>x.id===$('#work-template').value);if(!t)return;for(const key of ['type','product','dose','doseUnit','operator','equipmentId'])if(t[key]!==undefined&&form.elements[key])form.elements[key].value=t[key];};
