function openNote(id){const p=parcelById(id);if(!p)return;modal('Note de parcelle',p.nom,`<label class="field-label">Note<textarea id="parcel-note" data-autofocus>${escapeHtml(p.notes||'')}</textarea></label>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-note">Enregistrer</button>`,'small');$('#save-note').onclick=async()=>{await store.upsert('parcelles',{...p,notes:$('#parcel-note').value},{label:`Note mise à jour : ${p.nom}`});closeModal();toast('Note enregistrée.');};}

async function optimizeAttachmentFile(file){if(!file?.type?.startsWith('image/')||file.size<1400000)return{blob:file,name:file.name,mimeType:file.type};try{const bitmap=await createImageBitmap(file),maxSide=2200,scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();const mime='image/jpeg',blob=await new Promise(resolve=>canvas.toBlob(resolve,mime,.86));if(!blob||blob.size>=file.size)return{blob:file,name:file.name,mimeType:file.type};const base=file.name.replace(/\.[^.]+$/,'');return{blob,name:`${base}.jpg`,mimeType:mime};}catch{return{blob:file,name:file.name,mimeType:file.type};}}

function attachmentAssociationFields({parcelId=null,interventionId=null,equipmentId=null,clientId=null,chantierId=null}={}){
  const data=state(),parcels=active('parcelles',data),works=active('interventions',data).sort((a,b)=>String(workDate(b)).localeCompare(String(workDate(a)))).slice(0,250),equipment=active('materiels',data),clients=active('clients',data),chantiers=active('chantiers',data);
  return `<div class="form-grid"><label>Parcelle<select name="parcelId"><option value="">Non rattaché</option>${parcels.map(x=>`<option value="${x.id}" ${parcelId===x.id?'selected':''}>${escapeHtml(x.nom)}</option>`).join('')}</select></label><label>Travail<select name="interventionId"><option value="">Non rattaché</option>${works.map(x=>`<option value="${x.id}" ${interventionId===x.id?'selected':''}>${escapeHtml(x.type||'Travail')} · ${escapeHtml(parcelById(x.parcelId,data)?.nom||'Parcelle')} · ${localDate(workDate(x))}</option>`).join('')}</select></label><label>Matériel<select name="equipmentId"><option value="">Non rattaché</option>${equipment.map(x=>`<option value="${x.id}" ${equipmentId===x.id?'selected':''}>${escapeHtml(x.nom)}</option>`).join('')}</select></label><label>Client<select name="clientId"><option value="">Non rattaché</option>${clients.map(x=>`<option value="${x.id}" ${clientId===x.id?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label class="span-2">Chantier<select name="chantierId"><option value="">Non rattaché</option>${chantiers.map(x=>`<option value="${x.id}" ${chantierId===x.id?'selected':''}>${escapeHtml(x.type||'Chantier')} · ${localDate(x.plannedDate||x.createdAt)}</option>`).join('')}</select></label></div>`;
}

