  modal(photoOnly?'Ajouter une photo':'Ajouter une pièce jointe','Le fichier reste local tant que la synchronisation cloud n’est pas activée.',`<form id="attachment-form"><label class="field-label">Fichier<input name="file" type="file" required ${photoOnly?'accept="image/*" capture="environment"':'accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt"'}></label>${photoOnly?'':`<div class="form-grid" style="margin-top:12px"><label>Catégorie<select name="category">${categories}</select></label><label>Date du document<input name="documentDate" type="date" value="${todayIso()}"></label><label class="span-2">Tags<input name="tags" maxlength="160" placeholder="analyse sol, facture, semis…"></label></div>`}<label class="field-label" style="margin-top:12px">Commentaire<input name="note" maxlength="240"></label><details class="form-section" open><summary>Rattacher à…</summary>${attachmentAssociationFields({parcelId,interventionId,equipmentId,clientId,chantierId})}</details></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-attachment">Enregistrer</button>`,'large');
