  modal('Stocks',`${rows.length} article${rows.length!==1?'s':''} · valeur estimée ${formatEuro(summary.totalValue)}`,`<div class="preview-summary"><div class="preview-stat"><strong>${rows.length}</strong><small>articles</small></div><div class="preview-stat"><strong>${formatEuro(summary.totalValue)}</strong><small>valeur estimée</small></div><div class="preview-stat"><strong>${summary.low.length}</strong><small>stocks faibles</small></div><div class="preview-stat"><strong>${summary.movements.length}</strong><small>mouvements</small></div></div><div class="stack-list">${rows.length?rows.map(x=>`<div class="list-row"><div><strong>${escapeHtml(x.name||'Produit')}</strong><small>${escapeHtml(x.category||'Intrant')} · ${formatNumber(x.quantity)} ${escapeHtml(x.unit||'')} · ${formatEuro(x.value)}${x.alertBelow!==null&&x.alertBelow!==undefined&&toNumber(x.quantity)<=toNumber(x.alertBelow)?' · stock faible':''}</small></div><div><button class="small-button" data-action="stock-movement" data-id="${x.id}">Mouvement</button> <button class="small-button" data-action="edit-stock" data-id="${x.id}">Modifier</button></div></div>`).join(''):'<div class="empty-state">Aucun stock suivi.</div>'}</div>${summary.movements.length?`<h3>Derniers mouvements</h3><div class="stack-list">${summary.movements.slice(0,8).map(m=>{const item=rows.find(x=>x.id===m.stockItemId);return`<div class="list-row"><div><strong>${escapeHtml(item?.name||'Produit supprimé')}</strong><small>${localDate(m.date)} · ${escapeHtml(m.type||'')} · ${m.delta>=0?'+':''}${formatNumber(m.delta??m.quantity)} ${escapeHtml(item?.unit||'')}</small></div><strong>${formatNumber(m.balanceAfter)} ${escapeHtml(item?.unit||'')}</strong></div>`}).join('')}</div>`:''}`,`<button class="button secondary" data-action="print-stock-report">Rapport</button><button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" data-action="new-stock">＋ Stock</button>`,'large');
