function openStockForm(item=null){const x=item||{name:'',category:'Intrant',quantity:0,unit:'kg',unitPrice:null,alertBelow:null,note:''};modal(item?'Modifier le stock':'Nouveau stock','La quantité initiale peut ensuite être suivie par mouvements.',`<form id="stock-form" class="form-grid"><label>Nom *<input name="name" required value="${escapeHtml(x.name||'')}"></label><label>Catégorie<select name="category">${['Intrant','Semence','Engrais','Produit','Carburant','Fourniture','Autre'].map(v=>`<option ${x.category===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Quantité<input name="quantity" type="number" step="0.01" min="0" value="${x.quantity??0}" ${item?'readonly':''}></label><label>Unité<select name="unit">${['kg','L','t','m³','unités','sacs'].map(v=>`<option ${x.unit===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Prix unitaire (€)<input name="unitPrice" type="number" step="0.0001" min="0" value="${x.unitPrice??''}"></label><label>Alerte sous<input name="alertBelow" type="number" step="0.01" min="0" value="${x.alertBelow??''}"></label><label class="span-2">Note<textarea name="note">${escapeHtml(x.note||'')}</textarea></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button>${item?'<button class="button danger" id="delete-stock">Supprimer</button>':''}<button class="button primary" id="save-stock">Enregistrer</button>`,'small');$('#save-stock').onclick=async()=>{const v=Object.fromEntries(new FormData($('#stock-form')));v.quantity=toNumber(v.quantity);v.unitPrice=toNullableNumber(v.unitPrice);v.alertBelow=toNullableNumber(v.alertBelow);await store.upsert('stockItems',{...x,...v},{label:'Stock enregistré.'});closeModal();openStock();};$('#delete-stock')?.addEventListener('click',()=>confirmDelete('stockItems',x.id,'ce stock'));}
function openStockMovementForm(stockItemId){const item=store.get('stockItems',stockItemId);if(!item)return;modal('Mouvement de stock',`${item.name} · disponible ${formatNumber(item.quantity)} ${item.unit||''}`,`<form id="stock-movement-form" class="form-grid"><label>Type<select name="type"><option>Entrée</option><option>Sortie</option><option>Ajustement</option></select></label><label>Date<input name="date" type="date" value="${todayIso()}"></label><label>Quantité<input name="quantity" type="number" min="0" step="0.01" required></label><label>Prix unitaire (€)<input name="unitPrice" type="number" min="0" step="0.0001" value="${item.unitPrice??''}"></label><label class="span-2">Note<textarea name="note" placeholder="Achat, utilisation, inventaire…"></textarea></label></form><div class="notice info">Pour « Ajustement », la quantité saisie devient le nouveau stock réel.</div>`,`<button class="button secondary" data-action="open-stock">Annuler</button><button class="button primary" id="save-stock-movement">Enregistrer</button>`,'small');$('#save-stock-movement').onclick=async()=>{const form=$('#stock-movement-form');if(!form.reportValidity())return;const v=Object.fromEntries(new FormData(form));v.quantity=toNumber(v.quantity);v.unitPrice=toNullableNumber(v.unitPrice);await store.recordStockMovement({...v,stockItemId});openStock();toast('Mouvement de stock enregistré.');};}
function openPrivacy(){const p=state().preferences,c=nativeCapabilities();modal('Confidentialité','Contrôlez les fonctions qui utilisent des données sensibles ou un service externe.',`<div class="definition-list"><div><dt>GPS</dt><dd>${p.gpsConsent?'Autorisé après action':'Désactivé'}</dd></div><div><dt>Synchronisation cloud</dt><dd>${p.syncEnabled?'Activée si configurée':'Désactivée'}</dd></div><div><dt>Pièces jointes cloud</dt><dd>${p.syncAttachments?'Autorisées lors de la synchronisation':'Désactivées'}</dd></div><div><dt>IA distante</dt><dd>${p.remoteAiEnabled?'Activée explicitement':'Désactivée'}</dd></div><div><dt>Automatisations</dt><dd>${p.automationEnabled!==false?'Locales activées':'Désactivées'}</dd></div><div><dt>Mode iPhone natif</dt><dd>${c.native?`Actif · ${c.platform}`:'Non actif dans cette session'}</dd></div><div><dt>Biométrie</dt><dd>${p.biometricLock?'Demandée si le plugin natif est disponible':'Désactivée'}</dd></div><div><dt>Données locales</dt><dd>IndexedDB sur cet appareil</dd></div></div><p class="form-note">Aucune position GPS n’est envoyée automatiquement. Les règles d’automatisation sont évaluées localement. Les clés privées ne doivent jamais être intégrées au code public.</p>`,`<button class="button secondary" data-action="open-settings">Modifier les réglages</button><button class="button primary" data-action="close-modal">Fermer</button>`,'small');}
function startVoiceAssistant(){if(!state().preferences.voiceEnabled){toast('Les commandes vocales sont désactivées dans Paramètres.','error');return;}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('La reconnaissance vocale Web n’est pas disponible dans ce navigateur. Utilisez la dictée du clavier iPhone.','error');return;}const r=new SR();r.lang='fr-FR';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const text=e.results?.[0]?.[0]?.transcript||'';if(!text)return;openAssistant();setTimeout(()=>{const input=$('#assistant-input');if(input){input.value=text;assistantAnswer(text,{fromVoice:true});input.value='';}},50);};r.onerror=e=>toast(`Voix indisponible : ${e.error}`,'error');r.start();toast('Parlez maintenant…');}


function integrationFormatLabel(format){return({GPX:'GPX',KML:'KML',CSV:'CSV / machine',ISOXML:'ISOXML'}[format]||format||'Import');}
function integrationTrackLabel(track){const distance=Number(track.distanceMeters||0)/1000;return `${formatNumber(distance)} km · ${(track.points||[]).length} points${track.matchedParcels?.length?` · ${track.matchedParcels.length} parcelle(s)`:''}`;}
function openIntegrations(){
  const data=state(),tracks=active('gpsTracks',data).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)),imports=active('integrationImports',data).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)),stations=active('weatherStations',data).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)),caps=integrationCapabilities();
  modal('Intégrations agricoles','GPS, machines et stations météo sans modifier vos données tant que vous ne validez pas.',`<div class="preview-summary"><div class="preview-stat"><strong>${tracks.length}</strong><small>traces GPS</small></div><div class="preview-stat"><strong>${imports.length}</strong><small>imports</small></div><div class="preview-stat"><strong>${stations.length}</strong><small>stations</small></div></div><div class="notice info">Formats actifs : GPX, KML et CSV. ISOXML est détecté et archivé comme import machine, mais sa conversion automatique en travaux n’est pas encore activée.</div><label class="file-drop" style="margin-top:14px"><strong>Importer un fichier agricole</strong><small>GPX, KML, CSV/TXT ou XML/ISOXML</small><input id="integration-file-input" type="file" accept=".gpx,.kml,.csv,.txt,.xml" multiple></label>${tracks.length?`<h3>Traces récentes</h3><div class="stack-list">${tracks.slice(0,20).map(t=>`<button class="menu-row" data-action="open-integration-track" data-id="${t.id}"><span>⌁</span><span><strong>${escapeHtml(t.name||'Trace GPS')}</strong><small>${escapeHtml(integrationTrackLabel(t))}</small></span><b>›</b></button>`).join('')}</div>`:''}${stations.length?`<h3>Stations météo importées</h3><div class="stack-list">${stations.slice(0,10).map(st=>`<div class="list-row"><div><strong>${escapeHtml(st.name||'Station')}</strong><small>${st.summary?.count||0} relevés · pluie ${st.summary?.rainTotalMm==null?'—':`${formatNumber(st.summary.rainTotalMm)} mm`} · T° moy. ${st.summary?.temperatureAvg==null?'—':`${formatNumber(st.summary.temperatureAvg)} °C`}</small></div></div>`).join('')}</div>`:''}${imports.length?`<h3>Historique d’import</h3><div class="stack-list">${imports.slice(0,12).map(i=>`<div class="list-row"><div><strong>${escapeHtml(i.fileName||'Import')}</strong><small>${escapeHtml(integrationFormatLabel(i.format))} · ${i.createdAt?localDateTime(i.createdAt):'—'}${i.warning?` · ${escapeHtml(i.warning)}`:''}</small></div></div>`).join('')}</div>`:''}<details style="margin-top:14px"><summary>État des connecteurs</summary><dl class="definition-list"><div><dt>GPX/KML</dt><dd>${caps.gpx&&caps.kml?'Actif':'Indisponible'}</dd></div><div><dt>CSV machine</dt><dd>${caps.machineCsv?'Actif':'Indisponible'}</dd></div><div><dt>Station météo CSV</dt><dd>${caps.weatherStationCsv?'Actif':'Indisponible'}</dd></div><div><dt>ISOXML</dt><dd>${caps.isoxmlConversion?'Conversion active':'Détection uniquement'}</dd></div><div><dt>Satellite / API Geofolia</dt><dd>Non configuré</dd></div></dl></details>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');
  $('#integration-file-input')?.addEventListener('change',async event=>{const files=[...(event.target.files||[])];if(!files.length)return;try{await importAgriculturalFiles(files);openIntegrations();}catch(error){toast(error.message,'error');}});
}

async function importAgriculturalFiles(files){
  let imported=0,trackCount=0,stationCount=0,waypointCount=0;
  for(const file of files){
    const text=await file.text();const result=inspectAgriculturalText(file.name,text);const importId=uid('integration');const machineRows=(result.machineRows||[]).slice(0,2000);
    const importedTracks=[];
    for(const raw of result.traces||[]){
      const matches=state().preferences.integrationAutoMatch===false?[]:matchTraceToParcels(raw,active('parcelles'));
      const entity=await store.upsert('gpsTracks',{...raw,id:uid('gps'),importId,fileName:file.name,format:result.format,matchedParcels:matches,source:'integration'},{label:`Trace GPS importée : ${raw.name||file.name}`});
      importedTracks.push(entity.id);trackCount++;
    }
    for(const wp of result.waypoints||[]){await store.upsert('points',{name:wp.name||`Point ${file.name}`,latitude:wp.latitude,longitude:wp.longitude,type:'GPS importé',notes:`Import ${file.name}`,source:'integration',sourceId:importId},{label:`Point GPS importé : ${wp.name||file.name}`});waypointCount++;}
    if((result.stationReadings||[]).length){const readings=result.stationReadings.slice(-5000),summary=stationSummary(readings);await store.upsert('weatherStations',{name:file.name.replace(/\.[^.]+$/,''),importId,fileName:file.name,readings,summary,source:'integration'},{label:`Station météo importée : ${file.name}`});stationCount++;}
    await store.upsert('integrationImports',{id:importId,fileName:file.name,format:result.format,summary:result.summary||{},trackIds:importedTracks,machineRows,warning:result.warning||null,source:'integration'},{label:`Intégration agricole : ${file.name}`});
    imported++;
  }
  await store.mutate('Date de dernière intégration mise à jour.',s=>{s.metadata.lastIntegrationAt=Date.now();if(stationCount)s.metadata.lastStationImportAt=Date.now();},{queue:false,log:false});
  toast(`${imported} fichier(s) importé(s) · ${trackCount} trace(s) · ${waypointCount} point(s) · ${stationCount} station(s).`,'success');
}

function openIntegrationTrack(id){
  const track=store.get('gpsTracks',id);if(!track)return;const data=state();const matches=track.matchedParcels||[];const duration=Number(track.durationMs||0);const hours=Math.floor(duration/3600000),mins=Math.round((duration%3600000)/60000);
  modal(track.name||'Trace GPS',`${escapeHtml(track.format||'GPS')} · ${track.createdAt?localDateTime(track.createdAt):''}`,`<div class="preview-summary"><div class="preview-stat"><strong>${formatNumber((track.distanceMeters||0)/1000)}</strong><small>km</small></div><div class="preview-stat"><strong>${track.points?.length||0}</strong><small>points</small></div><div class="preview-stat"><strong>${duration?`${hours}h${String(mins).padStart(2,'0')}`:'—'}</strong><small>durée</small></div></div>${matches.length?`<h3>Rapprochement parcellaire</h3><div class="stack-list">${matches.map(m=>{const p=parcelById(m.parcelId,data);return p?`<button class="menu-row" data-action="open-parcel" data-id="${p.id}"><span>◇</span><span><strong>${escapeHtml(p.nom)}</strong><small>${Math.round((m.share||0)*100)} % des points de la trace</small></span><b>›</b></button>`:''}).join('')}</div>`:'<div class="notice warning">Aucune parcelle n’a été reconnue automatiquement sur cette trace.</div>'}<div class="notice info">Le rapprochement est une aide : il compte les points GPS situés dans les géométries des parcelles. Vérifiez toujours avant de créer un travail.</div>`,`<button class="button secondary" data-action="open-integrations">Retour</button><button class="button secondary" data-action="show-integration-track" data-id="${track.id}">Voir sur la carte</button>${matches.length?`<button class="button primary" data-action="suggest-work-from-track" data-id="${track.id}">Préparer des travaux</button>`:''}`,'large');
}

async function suggestWorkFromTrack(id){
  const track=store.get('gpsTracks',id);if(!track)return;const suggestions=buildTraceWorkSuggestions(track,track.matchedParcels||[],{trackId:id});if(!suggestions.length){toast('Aucune suggestion suffisamment fiable sur cette trace.','error');return;}
  const names=suggestions.map(s=>parcelById(s.parcelId)?.nom||s.parcelId);
  if(!confirm(`Créer ${suggestions.length} travail(aux) en brouillon à partir de cette trace ?\n\n${names.join('\n')}`))return;
  await store.upsertMany('interventions',suggestions,{label:`${suggestions.length} travail(aux) brouillon préparé(s) depuis une trace GPS`});toast('Travaux préparés en brouillon. Vérifiez-les avant validation.','success');closeModal();switchView('work');renderWork(state());
}

function showIntegrationTrack(id){
  const track=store.get('gpsTracks',id),first=track?.points?.[0];if(!first)return toast('Cette trace ne contient aucun point exploitable.','error');closeModal();switchView('map');setTimeout(()=>{parcelMap.map?.setView([first.latitude,first.longitude],16);const best=track.matchedParcels?.[0];if(best){selectedParcelId=best.parcelId;renderMapSheet();}},50);
}

function openReports(){modal('Rapports & exports','Exportez ou imprimez uniquement ce dont vous avez besoin.',`<div class="stack-list"><button class="menu-row" data-action="print-traceability-report"><span>PDF</span><span><strong>Registre de traçabilité</strong><small>Interventions, produits, opérateurs et pièces jointes</small></span><b>›</b></button><button class="menu-row" data-action="print-document-report"><span>PDF</span><span><strong>Registre documentaire</strong><small>Documents classés et rattachements</small></span><b>›</b></button><button class="menu-row" data-action="print-pilotage-report"><span>PDF</span><span><strong>Pilotage de campagne</strong><small>Produit brut, charges et marge estimée</small></span><b>›</b></button><button class="menu-row" data-action="print-farm-report"><span>PDF</span><span><strong>Rapport exploitation</strong><small>Assolement, travaux et coûts</small></span><b>›</b></button><button class="menu-row" data-action="print-stock-report"><span>PDF</span><span><strong>État des stocks</strong><small>Valorisation et mouvements</small></span><b>›</b></button><button class="menu-row" data-action="export-traceability-csv"><span>CSV</span><span><strong>Traçabilité</strong><small>Registre de campagne exploitable dans un tableur</small></span><b>›</b></button><button class="menu-row" data-action="export-document-csv"><span>CSV</span><span><strong>Documents</strong><small>Inventaire et rattachements</small></span><b>›</b></button><button class="menu-row" data-action="export-work-csv"><span>CSV</span><span><strong>Travaux</strong><small>Historique complet</small></span><b>›</b></button><button class="menu-row" data-action="export-parcels-csv"><span>CSV</span><span><strong>Parcelles</strong><small>Liste et attributs</small></span><b>›</b></button><button class="menu-row" data-action="export-geojson"><span>GEO</span><span><strong>GeoJSON</strong><small>Parcelles avec géométries</small></span><b>›</b></button></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');}

function openStatistics(campaign=campaignFor()){
  const p=buildPilotage(state(),{campaign}),delta=p.current.margin-p.previous.margin;
  const cultureRows=p.byCulture.map(x=>`<div class="list-row"><div><strong>${escapeHtml(x.culture)}</strong><small>${formatNumber(x.area)} ha · produit ${formatEuro(x.productHa)}/ha · charges ${formatEuro(x.costHa)}/ha</small></div><strong class="${x.margin<0?'negative':''}">${formatEuro(x.marginHa)}/ha</strong></div>`).join('');
  const parcelRows=p.parcelRows.slice(0,10).map(x=>`<button class="list-row is-button" data-action="open-parcel" data-id="${x.parcel.id}"><div><strong>${escapeHtml(x.parcel.nom)}</strong><small>${escapeHtml(x.parcel.culture||'')} · ${formatNumber(x.area)} ha · charges ${formatEuro(x.costHa)}/ha</small></div><strong class="${x.margin<0?'negative':''}">${formatEuro(x.marginHa)}/ha</strong></button>`).join('');
  const machineRows=p.equipment.slice(0,6).map(x=>`<button class="list-row is-button" data-action="open-equipment-detail" data-id="${x.id}"><div><strong>${escapeHtml(x.name)}</strong><small>${formatNumber(x.workHours)} h · travail ${formatEuro(x.workCost)} · entretien ${formatEuro(x.maintenanceCost)}</small></div><strong>${formatEuro(x.totalKnownCost)}</strong></button>`).join('');
  modal('Pilotage',`Campagne ${p.campaign}`,`<div class="preview-summary"><div class="preview-stat"><strong>${formatEuro(p.grossProduct)}</strong><small>produit brut estimé</small></div><div class="preview-stat"><strong>${formatEuro(p.charges)}</strong><small>charges</small></div><div class="preview-stat"><strong class="${p.margin<0?'negative':''}">${formatEuro(p.margin)}</strong><small>marge brute estimée</small></div><div class="preview-stat"><strong>${formatEuro(p.marginHa)}/ha</strong><small>marge moyenne</small></div><div class="preview-stat"><strong>${formatEuro(p.stock.value)}</strong><small>valeur stocks</small></div><div class="preview-stat"><strong>${p.stock.lowCount}</strong><small>stocks faibles</small></div></div><div class="notice ${delta<0?'warning':'info'}">Comparaison ${escapeHtml(p.previousCampaign)} → ${escapeHtml(p.campaign)} : marge estimée ${delta>=0?'+':''}${formatEuro(delta)}. Les campagnes sans données économiques complètes peuvent afficher 0 €.</div><h3>Performance par culture</h3><div class="stack-list">${cultureRows||'<div class="empty-state">Renseignez rendement et prix dans les fiches parcelles pour calculer le produit brut.</div>'}</div><h3>Parcelles</h3><div class="stack-list">${parcelRows||'<div class="empty-state">Aucune parcelle.</div>'}</div><h3>Matériel · coût connu</h3><div class="stack-list">${machineRows||'<div class="empty-state">Aucun matériel.</div>'}</div>`,`<button class="button secondary" data-action="pilotage-campaign" data-campaign="${escapeHtml(p.previousCampaign)}">← ${escapeHtml(p.previousCampaign)}</button>${campaign!==campaignFor()?`<button class="button secondary" data-action="pilotage-campaign" data-campaign="${escapeHtml(campaignFor())}">Campagne actuelle</button>`:''}<button class="button secondary" data-action="print-pilotage-report" data-campaign="${escapeHtml(campaign)}">Rapport PDF</button><button class="button secondary" data-action="open-stock">Stocks</button><button class="button primary" data-action="close-modal">Fermer</button>`,'large');
}

function openCampaignPlanner(){
  const data=state(),current=campaignFor(),next=nextCampaignId(current),parcels=active('parcelles',data).filter(p=>(p.ownershipType||'own')==='own'&&!p.archived),rotations=active('rotations',data),known=[...new Set([...parcels.map(p=>p.culture),...rotations.map(r=>r.culture)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'));
  modal('Planifier la campagne',`Préparer ${next} sans modifier la culture actuelle.`,`<form id="campaign-planner" class="stack-list">${parcels.map(p=>{const existing=rotations.find(r=>r.parcelId===p.id&&r.campaignId===next);return`<label class="list-row"><span><strong>${escapeHtml(p.nom)}</strong><small>Actuel : ${escapeHtml(p.culture||'—')} · ${formatNumber(p.surfaceHa)} ha</small></span><input list="campaign-cultures" data-parcel-id="${p.id}" value="${escapeHtml(existing?.culture||p.culture||'')}" style="min-height:42px;border:1px solid var(--border);border-radius:10px;padding:0 10px;width:min(220px,48vw)"></label>`}).join('')}<datalist id="campaign-cultures">${known.map(c=>`<option value="${escapeHtml(c)}"></option>`).join('')}</datalist></form>`,`<button class="button secondary" data-action="open-rotations">Annuler</button><button class="button primary" id="save-campaign-plan">Enregistrer ${next}</button>`,'large');
  $('#save-campaign-plan').onclick=async()=>{const rows=[];for(const input of $$('#campaign-planner [data-parcel-id]')){const culture=input.value.trim();if(!culture)continue;const old=rotations.find(r=>r.parcelId===input.dataset.parcelId&&r.campaignId===next);rows.push({...old,parcelId:input.dataset.parcelId,campaignId:next,culture,source:'local'});}if(!rows.length)return toast('Aucune culture renseignée.','error');await store.upsertMany('rotations',rows,{label:`Plan de campagne ${next} enregistré`});openRotations();toast(`${rows.length} parcelle(s) planifiée(s) pour ${next}.`);};
}
async function openDataCenter(){const data=state(),backups=await store.storage.backupList(store.workspaceContext().id);const deleted=ENTITY_TYPES.reduce((sum,t)=>sum+(data[t]||[]).filter(i=>i.deletedAt).length,0);modal('Mes données','Import, sauvegardes et maintenance de l’application.',`<div class="settings-group"><h2>Importer et restaurer</h2><button class="menu-row" data-action="choose-import"><span>⇩</span><span><strong>Importer</strong><small>Excel, CSV, XML, GeoJSON ou SHP</small></span><b>›</b></button><button class="menu-row" data-action="choose-restore"><span>↶</span><span><strong>Restaurer une sauvegarde</strong><small>ZIP complet ou JSON</small></span><b>›</b></button>${backups.length?`<button class="menu-row" data-action="open-auto-backups"><span>⟲</span><span><strong>Sauvegardes automatiques</strong><small>${backups.length} snapshot${backups.length>1?'s':''} local${backups.length>1?'aux':''}</small></span><b>›</b></button>`:''}<button class="menu-row" data-action="open-import-history"><span>◷</span><span><strong>Historique des imports</strong><small>${active('importSessions',data).length} session${active('importSessions',data).length!==1?'s':''}</small></span><b>›</b></button></div><div class="settings-group"><h2>Sauvegarder</h2><button class="menu-row" data-action="export-complete-backup"><span>⇧</span><span><strong>Sauvegarde complète</strong><small>Données + photos + documents</small></span><b>›</b></button><button class="menu-row" data-action="export-json-backup"><span>{ }</span><span><strong>Sauvegarde JSON</strong><small>Données structurées sans fichiers binaires</small></span><b>›</b></button><button class="menu-row" data-action="export-encrypted-backup"><span>🔒</span><span><strong>Sauvegarde chiffrée</strong><small>AES-GCM avec mot de passe · données structurées</small></span><b>›</b></button></div><div class="settings-group"><h2>Maintenance</h2><button class="menu-row" data-action="open-quality"><span>✓</span><span><strong>Qualité des données</strong><small>${dataQuality(data).score}% complets</small></span><b>›</b></button><button class="menu-row" data-action="open-trash"><span>♲</span><span><strong>Corbeille</strong><small>${deleted} élément${deleted!==1?'s':''}</small></span><b>›</b></button><button class="menu-row" data-action="open-log"><span>◷</span><span><strong>Activité</strong><small>${data.journal.length} événements locaux</small></span><b>›</b></button><button class="menu-row" data-action="open-sync"><span>☁</span><span><strong>Synchronisation</strong><small>${escapeHtml(sync.status.message)}</small></span><b>›</b></button><button class="menu-row" data-action="open-security"><span>⌾</span><span><strong>Sécurité & appareils</strong><small>Cloud, file d’attente, appareils et export chiffré</small></span><b>›</b></button><button class="menu-row" data-action="open-diagnostic"><span>ⓘ</span><span><strong>Diagnostic</strong><small>Build, stockage, service worker</small></span><b>›</b></button></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');}
async function openAutoBackups(){const backups=await store.storage.backupList(store.workspaceContext().id);const periodLabel=p=>({daily:'Quotidienne',weekly:'Hebdomadaire',monthly:'Mensuelle'}[p]||String(p||'Sauvegarde'));modal('Sauvegardes automatiques','Rétention : 7 quotidiennes, 4 hebdomadaires et 3 mensuelles. Chaque sauvegarde locale est contrôlée par checksum.',backups.length?`<div class="stack-list">${backups.map(b=>`<div class="list-row"><div><strong>${escapeHtml(periodLabel(b.period))} ${b.verified?'✓':''}</strong><small>${escapeHtml(localDateTime(b.createdAt))} · ${b.verified?'Vérifiée':'À vérifier'} · ${escapeHtml(b.id)}</small></div><div><button class="small-button" data-action="verify-auto-backup" data-id="${escapeHtml(b.id)}">Vérifier</button> <button class="small-button" data-action="export-auto-backup" data-id="${escapeHtml(b.id)}">Exporter</button> <button class="small-button" data-action="restore-auto-backup" data-id="${escapeHtml(b.id)}">Restaurer</button> <button class="small-button danger" data-action="delete-auto-backup" data-id="${escapeHtml(b.id)}">Supprimer</button></div></div>`).join('')}</div>`:'<div class="empty-state">Aucune sauvegarde automatique locale.</div>',`<button class="button secondary" id="verify-all-backups">Vérifier toutes</button><button class="button secondary" data-action="open-data-center">Retour</button>`,'large');$('#verify-all-backups')?.addEventListener('click',async()=>{const rows=await store.storage.backupVerifyAll(store.workspaceContext().id);toast(`${rows.filter(x=>x.ok).length}/${rows.length} sauvegarde(s) vérifiée(s).`);openAutoBackups();});}
async function exportAutoBackup(id){const backup=await store.storage.backupGet(id);if(!backup?.state)throw new Error('Sauvegarde locale introuvable.');const payload=await makeBackup(backup.state);download(`parcelles-backup-local-${String(id).replace(/[^a-z0-9_-]+/gi,'-')}.json`,JSON.stringify(payload,null,2),'application/json;charset=utf-8');toast('Sauvegarde locale exportée.');}

function openImportHistory(){const rows=active('importSessions').sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));modal('Historique des imports','Chaque import conserve un point de restauration local tant qu’il est disponible.',rows.length?`<div class="stack-list">${rows.map(x=>`<div class="list-row"><div><strong>${localDateTime(x.createdAt)}</strong><small>${escapeHtml((x.fileNames||[]).join(', '))} · ${x.created||0} créée(s), ${x.updated||0} modifiée(s), ${x.interventions||0} travail(aux)</small></div><div>${x.rollbackBackupId?`<button class="small-button danger" data-action="rollback-import" data-id="${x.id}">Annuler cet import</button>`:''}</div></div>`).join('')}</div>`:'<div class="empty-state">Aucun import enregistré.</div>',`<button class="button secondary" data-action="open-data-center">Retour</button>`,'large');}
async function rollbackImport(id){if(!confirm('Restaurer exactement l’état précédent cet import ? Les modifications effectuées depuis cet import seront perdues.'))return;await rollbackImportSession(store,id);closeModal();toast('Import annulé : l’état précédent a été restauré.');renderAll();}
async function restoreAutoBackup(id){const verification=await store.storage.backupVerify(id);if(!verification.ok)throw new Error('La sauvegarde automatique a échoué au contrôle d’intégrité.');const backup=await store.storage.backupGet(id);if(!backup?.state)throw new Error('Sauvegarde automatique introuvable.');await exportCompleteBackup();await store.replaceState(backup.state,'Sauvegarde automatique restaurée.',{kind:'restore'});closeModal();toast('Sauvegarde vérifiée puis restaurée.');}

function openQuality(){const report=dataQuality(state());modal('Qualité des données','Chaque anomalie peut être ouverte et corrigée.',`<div class="quality-summary"><strong>${report.score}% complets</strong><div class="quality-progress"><span style="width:${report.score}%"></span></div></div><div class="stack-list">${report.issues.length?report.issues.map(i=>`<div class="list-row"><div><strong>${escapeHtml(i.label)}</strong><small>${escapeHtml(i.code)}</small></div><button class="small-button" data-action="quality-open" data-code="${i.code}">Corriger</button></div>`).join(''):'<div class="empty-state">✓ Aucune anomalie détectée.</div>'}</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');}
function openQualityIssue(code){const data=state(),report=dataQuality(data),issue=report.issues.find(i=>i.code===code);if(!issue){toast('Cette anomalie n’est plus présente.');openQuality();return;}if(code==='culture'){const rows=issue.ids.map(id=>parcelById(id,data)).filter(Boolean);modal('Cultures manquantes',issue.label,`<form id="quality-culture-form" class="stack-list">${rows.map(p=>`<label class="list-row"><span><strong>${escapeHtml(p.nom)}</strong><small>${formatNumber(p.surfaceHa)} ha · ${escapeHtml(p.commune||'')}</small></span><input data-parcel-id="${p.id}" placeholder="Culture" style="min-height:42px;border:1px solid var(--border);border-radius:10px;padding:0 10px;width:min(220px,48vw)"></label>`).join('')}</form>`,`<button class="button secondary" data-action="open-quality">Retour</button><button class="button primary" id="quality-save-cultures">Enregistrer</button>`,'large');$('#quality-save-cultures').onclick=async()=>{const updates=[];for(const input of $$('#quality-culture-form [data-parcel-id]')){if(!input.value.trim())continue;const p=parcelById(input.dataset.parcelId);if(p)updates.push({...p,culture:input.value.trim()});}if(!updates.length)return toast('Renseignez au moins une culture.','error');await store.upsertMany('parcelles',updates,{label:`Correction qualité : ${updates.length} cultures renseignées`});openQuality();toast(`${updates.length} parcelle(s) corrigée(s).`);};return;}let rows=[];if(issue.kind==='parcels')rows=issue.ids.map(id=>parcelById(id,data)).filter(Boolean).map(p=>`<div class="list-row"><div><strong>${escapeHtml(p.nom)}</strong><small>${escapeHtml(p.culture||'Culture manquante')} · ${p.surfaceHa??'surface manquante'}${p.geometry?'':' · sans géométrie'}</small></div><button class="small-button" data-action="edit-parcel" data-id="${p.id}">Modifier</button></div>`);else if(issue.kind==='interventions')rows=issue.ids.map(id=>store.get('interventions',id)).filter(Boolean).map(w=>`<div class="list-row"><div><strong>${escapeHtml(w.type||'Travail')}</strong><small>${localDate(w.date)}</small></div><button class="small-button" data-action="edit-work" data-id="${w.id}">Modifier</button></div>`);else rows=issue.ids.map(id=>{const doc=store.get('documents',id)||store.get('photos',id);const type=store.get('documents',id)?'documents':'photos';return doc?`<div class="list-row"><div><strong>${escapeHtml(doc.name||id)}</strong><small>${escapeHtml(doc.category||'Pièce jointe')} · ${escapeHtml(documentContextText(data,doc))}</small></div><button class="small-button" data-action="view-attachment" data-type="${type}" data-id="${id}">Ouvrir</button></div>`:`<div class="list-row"><div><strong>${escapeHtml(id)}</strong><small>Pièce jointe introuvable</small></div></div>`;});modal('Corriger les données',issue.label,`<div class="stack-list">${rows.join('')}</div>`,`<button class="button secondary" data-action="open-quality">Retour</button>`,'large');}


function entityTypeLabel(type){return({parcelles:'Parcelle',interventions:'Travail',tasks:'Tâche',rotations:'Rotation',grazingSessions:'Pâturage',materiels:'Matériel',products:'Produit',clients:'Client',documents:'Document',photos:'Photo',points:'Point',templates:'Modèle',importSessions:'Import',syncConflicts:'Conflit',notifications:'Notification',observations:'Observation',stockItems:'Stock',stockMovements:'Mouvement de stock',maintenanceRecords:'Entretien',routeSessions:'Tournée'}[type]||type);}
function trashItemTitle(type,item){if(type==='parcelles')return item.nom||'Parcelle';if(type==='interventions')return item.type||'Travail';if(type==='tasks')return item.title||'Tâche';if(type==='materiels')return item.nom||'Matériel';if(type==='clients')return item.name||'Client';if(type==='documents'||type==='photos')return item.name||entityTypeLabel(type);if(type==='points')return item.nom||item.type||'Point';if(type==='observations')return item.title||item.type||'Observation';if(type==='stockItems')return item.name||'Stock';if(type==='stockMovements')return item.type||'Mouvement de stock';if(type==='maintenanceRecords')return item.type||'Entretien';return entityTypeLabel(type);}
function openTrash(){const data=state(),rows=[];for(const type of ENTITY_TYPES){for(const item of (data[type]||[]).filter(x=>x.deletedAt))rows.push({type,item});}rows.sort((a,b)=>(b.item.deletedAt||0)-(a.item.deletedAt||0));modal('Corbeille',rows.length?`${rows.length} élément${rows.length>1?'s':''} récupérable${rows.length>1?'s':''}.`:'La corbeille est vide.',rows.length?`<div class="notice warning">Les photos et documents restent stockés tant qu’ils sont dans la corbeille. « Vider la corbeille » est définitif.</div><div class="stack-list">${rows.map(({type,item})=>`<div class="list-row"><div><strong>${escapeHtml(trashItemTitle(type,item))}</strong><small>${escapeHtml(entityTypeLabel(type))} · supprimé ${localDateTime(item.deletedAt)}</small></div><div><button class="small-button" data-action="restore-trash" data-type="${type}" data-id="${item.id}">Restaurer</button> <button class="small-button danger" data-action="purge-trash" data-type="${type}" data-id="${item.id}">Définitif</button></div></div>`).join('')}</div>`:'<div class="empty-state">Aucun élément supprimé.</div>',`<button class="button secondary" data-action="open-data-center">Retour</button>${rows.length?'<button class="button danger" data-action="empty-trash">Vider la corbeille</button>':''}`,'large');}
async function emptyTrash(){const data=state(),rows=[];for(const type of ENTITY_TYPES)for(const item of (data[type]||[]).filter(x=>x.deletedAt))rows.push({type,id:item.id});if(!rows.length)return;if(!confirm(`Supprimer définitivement ${rows.length} élément(s) ? Cette action est irréversible.`))return;for(const row of rows)await store.purge(row.type,row.id);openTrash();toast('Corbeille vidée.');}

function openLog(){const entries=state().journal;modal('Activité','Les événements importants sont conservés localement.',entries.length?`<ul class="timeline">${entries.slice(0,100).map(i=>`<li><strong>${escapeHtml(i.message)}</strong><small>${localDateTime(i.createdAt)} · ${escapeHtml(i.type)}</small></li>`).join('')}</ul>`:'<div class="empty-state">Aucune activité.</div>',`<button class="button secondary" data-action="close-modal">Fermer</button>`);}
async function openAccountTeam(){
  const prefs=state().preferences;
  if(!prefs.syncEnabled){modal('Compte & équipe','Le cloud est facultatif : Parcelles fonctionne entièrement en local sans compte.',`<div class="notice info">Activez la synchronisation uniquement si vous souhaitez retrouver les mêmes données sur plusieurs appareils ou travailler en équipe.</div><p class="form-note">Une configuration Firebase sécurisée est nécessaire. Aucune donnée n’est envoyée tant que cette option reste désactivée.</p>`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" id="enable-cloud">Activer le cloud</button>`,'small');$('#enable-cloud').onclick=async()=>{await store.setPreferences({syncEnabled:true});await sync.init();closeModal();openAccountTeam();};return;}
  await sync.init();
  if(!sync.status.configured){modal('Compte & équipe','Configuration cloud requise.',`<div class="notice warning">${escapeHtml(sync.status.message)}</div><p>Renseignez <code>PARCELLES_FIREBASE_CONFIG</code> dans <strong>config.js</strong>, puis rechargez l’application. Les règles fournies dans le projet doivent être déployées avant toute utilisation réelle.</p>`,`<button class="button secondary" data-action="open-settings">Réglages</button><button class="button primary" data-action="close-modal">Fermer</button>`,'small');return;}
  if(!sync.user){modal('Se connecter','Un compte permet la synchronisation multi-appareils.',`<form id="cloud-auth-form" class="form-grid"><label class="span-2">Email<input name="email" type="email" autocomplete="email" required></label><label class="span-2">Mot de passe<input name="password" type="password" autocomplete="current-password" minlength="8" required></label></form><div class="notice info">Le premier compte d’une exploitation peut ensuite créer son espace cloud et inviter des collaborateurs.</div>`,`<button class="button secondary" id="cloud-signup">Créer un compte</button><button class="button primary" id="cloud-login">Se connecter</button>`,'small');const auth=async mode=>{const f=$('#cloud-auth-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));try{if(mode==='signup')await sync.signUp(v.email,v.password);else await sync.signIn(v.email,v.password);closeModal();renderNetwork();openAccountTeam();}catch(error){toast(error.message,'error');}};$('#cloud-login').onclick=()=>auth('login');$('#cloud-signup').onclick=()=>auth('signup');return;}
  const workspaces=await sync.listWorkspaces().catch(()=>[]);
  if(!sync.workspaceId||!sync.member){modal('Choisir une exploitation cloud',`Connecté : ${sync.user.email||sync.user.uid}`,`<div class="stack-list">${workspaces.length?workspaces.map(w=>`<button class="menu-row" data-workspace-id="${w.id}"><span>☁</span><span><strong>${escapeHtml(w.name||'Exploitation')}</strong><small>${escapeHtml(roleLabel(w.role||'viewer'))}</small></span><b>›</b></button>`).join(''):'<div class="empty-state">Aucune exploitation cloud liée à ce compte.</div>'}</div><hr><form id="create-workspace-form" class="form-grid"><label class="span-2">Nouvelle exploitation<input name="name" value="${escapeHtml(state().exploitation.nom||'Mon exploitation')}"></label></form><button class="button secondary" id="create-workspace">Créer l’espace</button><hr><form id="join-workspace-form" class="form-grid"><label class="span-2">Code d’invitation<input name="token" autocomplete="off" placeholder="Code reçu"></label></form><button class="button secondary" id="join-workspace">Rejoindre</button>`,`<button class="button secondary" id="cloud-signout">Se déconnecter</button><button class="button primary" data-action="close-modal">Fermer</button>`,'large');$$('[data-workspace-id]').forEach(b=>b.onclick=async()=>{await sync.selectWorkspace(b.dataset.workspaceId);closeModal();renderNetwork();openAccountTeam();});$('#create-workspace').onclick=async()=>{const name=new FormData($('#create-workspace-form')).get('name');try{await sync.createWorkspace(name);closeModal();renderNetwork();openAccountTeam();}catch(error){toast(error.message,'error');}};$('#join-workspace').onclick=async()=>{const token=new FormData($('#join-workspace-form')).get('token');try{await sync.acceptInvite(token);closeModal();renderNetwork();openAccountTeam();}catch(error){toast(error.message,'error');}};$('#cloud-signout').onclick=async()=>{await sync.signOut();closeModal();renderNetwork();openAccountTeam();};return;}
  const [members,devices,activity]=await Promise.all([sync.listMembers().catch(()=>[]),sync.listDevices().catch(()=>[]),sync.listActivity(12).catch(()=>[])]);
  const owner=sync.can('manage-members');
  modal('Compte & équipe',`${escapeHtml(sync.workspace?.name||state().exploitation.nom)} · ${escapeHtml(sync.roleName)}`,`<div class="preview-summary"><div class="preview-stat"><strong>${members.length}</strong><small>membres</small></div><div class="preview-stat"><strong>${devices.length}</strong><small>appareils</small></div><div class="preview-stat"><strong>${state().queue.filter(x=>x.status==='pending').length}</strong><small>à synchroniser</small></div></div><h3>Membres</h3><div class="stack-list">${members.map(m=>`<div class="list-row"><div><strong>${escapeHtml(m.email||m.uid)}</strong><small>${escapeHtml(roleLabel(m.role))}</small></div>${owner&&m.id!==sync.user.uid?`<select class="member-role-select" data-member-id="${m.id}">${cloudRoleOptions(m.role)}</select><button class="small-button danger" data-remove-member="${m.id}">Retirer</button>`:''}</div>`).join('')}</div>${owner?`<h3>Inviter</h3><form id="invite-form" class="form-grid"><label>Email<input name="email" type="email" required></label><label>Rôle<select name="role">${cloudRoleOptions('operator')}</select></label></form><button class="button secondary" id="create-invite">Créer un code d’invitation</button>`:''}<h3>Appareils</h3><div class="stack-list">${devices.length?devices.map(d=>`<div class="list-row"><div><strong>${escapeHtml(d.name||'Appareil')}</strong><small>${escapeHtml(d.email||'')} · ${d.lastSeen?localDateTime(d.lastSeen):'—'}</small></div>${d.id===sync.deviceId?'<span class="status-badge">Cet appareil</span>':''}</div>`).join(''):'<div class="empty-state">Aucun appareil enregistré.</div>'}</div><form id="device-name-form" class="form-grid"><label class="span-2">Nom de cet appareil<input name="name" value="${escapeHtml(readLocalText('parcelles:device-name')) }" placeholder="iPhone de Thibault"></label></form><button class="small-button" id="rename-device">Renommer</button>${activity.length?`<h3>Activité cloud récente</h3><div class="stack-list">${activity.map(a=>`<div class="list-row"><div><strong>${escapeHtml(a.action||'Action')}</strong><small>${escapeHtml(a.email||'')} · ${a.createdAt?localDateTime(a.createdAt):'—'}</small></div></div>`).join('')}</div>`:''}`,`<button class="button secondary" id="switch-workspace">Changer d’exploitation</button><button class="button secondary" id="cloud-signout">Se déconnecter</button><button class="button primary" data-action="open-sync">Synchroniser</button>`,'large');
  $$('.member-role-select').forEach(el=>el.onchange=async()=>{try{await sync.updateMemberRole(el.dataset.memberId,el.value);toast('Rôle mis à jour.');openAccountTeam();}catch(error){toast(error.message,'error');}});$$('[data-remove-member]').forEach(el=>el.onclick=async()=>{if(!confirm('Retirer ce membre de l’exploitation cloud ?'))return;try{await sync.removeMember(el.dataset.removeMember);toast('Membre retiré.');openAccountTeam();}catch(error){toast(error.message,'error');}});$('#create-invite')?.addEventListener('click',async()=>{const f=$('#invite-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));try{const invite=await sync.createInvite(v.email,v.role);const copied=await copyText(invite.token);toast(copied?`Code copié : ${invite.token}`:'Code créé. Copiez-le depuis la fenêtre suivante.',copied?'success':'error');modal('Invitation créée',`Pour ${invite.email}`,`<p>Envoyez ce code à la personne invitée :</p><pre class="diagnostic-pre">${escapeHtml(invite.token)}</pre><p class="form-note">Le code expire dans 7 jours et ne peut être utilisé que par l’adresse email prévue.</p>`,`<button class="button primary" data-action="open-account">Retour</button>`,'small');}catch(error){toast(error.message,'error');}});$('#rename-device').onclick=async()=>{const name=new FormData($('#device-name-form')).get('name');try{await sync.renameDevice(name);toast('Appareil renommé.');openAccountTeam();}catch(error){toast(error.message,'error');}};$('#switch-workspace').onclick=async()=>{await store.switchWorkspace('local');await sync.refreshMembership();closeModal();renderAll();renderNetwork();openAccountTeam();};$('#cloud-signout').onclick=async()=>{await sync.signOut();closeModal();renderNetwork();openAccountTeam();};
}

async function openSync(){
  const data=state(),stats=queueStats(data.queue),conflicts=active('syncConflicts',data).filter(c=>c.status==='open');
  modal('Synchronisation','File robuste, reprises automatiques et conflits explicites.',`<dl class="definition-list"><div><dt>État</dt><dd>${escapeHtml(sync.status.message)}</dd></div><div><dt>Rôle</dt><dd>${escapeHtml(sync.roleName)}</dd></div><div><dt>Prêtes</dt><dd>${stats.ready}</dd></div><div><dt>Temporisées</dt><dd>${stats.waiting}</dd></div><div><dt>En erreur</dt><dd>${stats.error}</dd></div><div><dt>Conflits</dt><dd>${conflicts.length}</dd></div><div><dt>Dernière sync</dt><dd>${data.metadata.lastSyncAt?localDateTime(data.metadata.lastSyncAt):'Aucune'}</dd></div></dl>${data.metadata.lastSyncError?`<div class="notice warning">Dernière erreur : ${escapeHtml(data.metadata.lastSyncError)}</div>`:''}${sync.lastResult?`<div class="notice info">Dernière opération : ${sync.lastResult.sent||0} envoyée(s), ${sync.lastResult.pulled||0} reçue(s), ${sync.lastResult.merged||0} fusion(s) sûre(s), ${sync.lastResult.errors||0} erreur(s), ${sync.lastResult.uploaded||0} fichier(s) envoyé(s), ${sync.lastResult.downloaded||0} reçu(s).</div>`:''}${conflicts.length?`<h3>Conflits à résoudre</h3><div class="stack-list">${conflicts.map(c=>`<button class="menu-row" data-action="open-sync-conflict" data-id="${c.id}"><span>!</span><span><strong>${escapeHtml(entityTypeLabel(c.entity))}</strong><small>${escapeHtml((c.conflictFields||[]).length?`Champs : ${c.conflictFields.join(', ')}`:c.entityId||'')}</small></span><b>›</b></button>`).join('')}</div>`:''}<div class="notice info" style="margin-top:14px">Une erreur réseau n’efface jamais la saisie locale. Les tentatives sont espacées progressivement et les opérations en échec restent visibles.</div>`,`<button class="button secondary" data-action="open-account">Compte & équipe</button><button class="button secondary" data-action="open-security">Sécurité</button>${stats.error?'<button class="button secondary" id="retry-sync-errors">Réessayer les erreurs</button>':''}<button class="button secondary" data-action="close-modal">Fermer</button>${sync.status.connected?'<button class="button primary" id="run-sync">Synchroniser maintenant</button>':''}`,'large');
  $('#retry-sync-errors')?.addEventListener('click',async()=>{await sync.retryFailed();openSync();toast('File de synchronisation réarmée.');});
  $('#run-sync')?.addEventListener('click',async()=>{const b=$('#run-sync');b.disabled=true;b.textContent='Synchronisation…';try{const r=await sync.sync({force:true});renderNetwork();openSync();toast(`${r.sent||0} envoyée(s), ${r.pulled||0} reçue(s), ${r.conflicts||0} conflit(s).`);}catch(error){b.disabled=false;b.textContent='Synchroniser maintenant';toast(error.message,'error');}});
}

function openSyncConflict(id){
  const c=store.get('syncConflicts',id);if(!c)return;const preview=value=>`<pre class="diagnostic-pre">${escapeHtml(JSON.stringify(value||{},null,2))}</pre>`;
  modal('Conflit de synchronisation',`${entityTypeLabel(c.entity)} · ${c.entityId}`,`${(c.conflictFields||[]).length?`<div class="notice warning">Champs réellement contradictoires : ${escapeHtml(c.conflictFields.join(', '))}</div>`:c.suggestedMerge?'<div class="notice info">Une fusion sûre est disponible : seules les valeurs vides d’un côté sont complétées par l’autre.</div>':''}<div class="conflict-grid"><section><h3>Sur cet appareil</h3>${preview(c.local)}</section><section><h3>Dans le cloud</h3>${preview(c.remote)}</section></div>`,`<button class="button secondary" data-action="open-sync">Annuler</button><button class="button secondary" data-action="resolve-sync-conflict" data-id="${c.id}" data-choice="remote">Utiliser le cloud</button>${c.suggestedMerge?`<button class="button secondary" data-action="resolve-sync-conflict" data-id="${c.id}" data-choice="merge">Fusion sûre</button>`:''}<button class="button primary" data-action="resolve-sync-conflict" data-id="${c.id}" data-choice="local">Conserver cet appareil</button>`,'large');
}
async function resolveSyncConflict(id,choice){
  const c=store.get('syncConflicts',id);if(!c)return;if(ENTITY_TYPES.includes(c.entity)){if(choice==='remote'&&c.remote){await store.applyRemote(c.entity,c.remote);await store.mutate('File de synchronisation mise à jour.',st=>{for(const item of st.queue){if(item.entity===c.entity&&item.entityId===c.entityId&&item.status==='conflict')item.status='done';}},{queue:false,log:false,bypassPermissions:true});}if(choice==='local'&&c.local)await store.upsert(c.entity,c.local,{label:'Conflit résolu avec la version locale.',queue:true});if(choice==='merge'&&c.suggestedMerge)await store.upsert(c.entity,c.suggestedMerge,{label:'Conflit résolu par fusion sûre.',queue:true});}
  await store.upsert('syncConflicts',{...c,status:choice==='remote'?'resolved-remote':choice==='merge'?'resolved-merge':'resolved-local',resolvedAt:Date.now()},{label:'Conflit de synchronisation résolu.',queue:false});openSync();toast('Conflit résolu.');
}

async function openDiagnostic(){
  const [estimate,deploy,health,backups,breakdown,swStatus]=await Promise.all([
    store.storage.estimate(),
    verifyDeployment().catch(error=>({ok:false,failed:[{path:'deployment',error:error.message}],results:[]})),
    storageHealth().catch(()=>({estimate:null,persisted:false})),
    store.storage.backupList(store.workspaceContext().id).catch(()=>[]),
    store.storage.breakdown().catch(()=>null),
    serviceWorkerStatus().catch(()=>null)
  ]);
  const reg=await navigator.serviceWorker?.getRegistration?.();const data=state();const blobs=await store.storage.blobKeys().catch(()=>[]),errors=getRecordedErrors();const perfRows=performanceHistory(),resources=resourceTimingSummary();
  const recentErrors=errors.filter(e=>Date.now()-Number(e.createdAt||0)<=24*3600*1000);const usagePct=estimate.quota?Math.round((estimate.usage||0)/(estimate.quota||1)*100):0;
  const checks=[
    {label:'Déploiement',ok:Boolean(deploy.ok),detail:deploy.ok?'Ressources cohérentes':`${deploy.failed?.length||0} ressource(s) en erreur`},
    {label:'Stockage local',ok:!store.storage.usingFallback,detail:store.storage.usingFallback?'Mode de secours':'IndexedDB opérationnel'},
    {label:'Service worker',ok:Boolean(reg),detail:reg?'Installé':'Absent'},
    {label:'Sauvegardes',ok:backups.length>0||!data.preferences.autoBackup,detail:backups.length?`${backups.length} sauvegarde(s) locale(s)`:data.preferences.autoBackup?'Aucune créée':'Automatiques désactivées'},
    {label:'Erreurs 24 h',ok:recentErrors.length===0,detail:recentErrors.length?`${recentErrors.length} erreur(s) enregistrée(s)`:'Aucune erreur enregistrée'},
    {label:'Cloud',ok:!data.preferences.syncEnabled||Boolean(sync?.status?.connected),detail:!data.preferences.syncEnabled?'Désactivé':sync?.status?.message||'Non initialisé'},
    {label:'Automatisations',ok:true,detail:`${active('automationRules',data).filter(r=>r.enabled).length} règle(s) active(s)`},
    {label:'Mode natif',ok:true,detail:nativeCapabilities().native?`Actif · ${nativeCapabilities().platform}`:'Web/PWA'}
  ];
  const diag={build:BUILD_ID,schema:APP_VERSION,revision:data.metadata.revision,userAgent:navigator.userAgent,language:navigator.language,online:navigator.onLine,serviceWorker:Boolean(reg),serviceWorkerController:Boolean(navigator.serviceWorker?.controller),serviceWorkerScope:reg?.scope||null,serviceWorkerReported:swStatus?.reported||null,indexedDbFallback:store.storage.usingFallback,storagePersisted:Boolean(health.persisted),storageUsage:estimate.usage,storageQuota:estimate.quota,storageUsagePercent:usagePct,blobCount:blobs.length,backupCount:backups.length,storageBreakdown:breakdown,performanceLatest:perfRows[0]||null,resourceTiming:resources,lastImportAt:data.metadata.lastImportAt,lastAutoBackupDay:data.metadata.lastAutoBackupDay,lastSyncAt:data.metadata.lastSyncAt,deploymentOk:deploy.ok,deploymentFailures:deploy.failed,counts:Object.fromEntries(['parcelles','interventions','tasks','photos','documents','points','clients','observations','stockItems','materiels','platformJobs'].map(t=>[t,active(t,data).length])),recentErrors:errors.slice(0,20),cloud:{enabled:Boolean(data.preferences.syncEnabled),connected:Boolean(sync?.status?.connected),workspaceId:data.preferences.workspaceId||null,workspaceStorage:store.workspaceContext(),role:sync?.role||'owner',deviceId:sync?.deviceId||null,user:sync?.user?.email||null,status:sync?.status?.message||null},platform:platformSummary(data,store.workspaceContext()),native:nativeCapabilities(),automations:{enabled:data.preferences.automationEnabled!==false,rules:active('automationRules',data).length,runs:active('automationRuns',data).length,lastRunAt:data.metadata.automationLastRunAt||null}};
  const failed=deploy.failed?.length?`<div class="notice danger"><strong>Ressources de déploiement manquantes</strong><br>${deploy.failed.map(x=>`${escapeHtml(x.path)} · ${escapeHtml(x.status||x.error||'erreur')}`).join('<br>')}</div>`:`<div class="notice info">✓ Toutes les ressources principales du déploiement répondent correctement.</div>`;
  const healthHtml=`<div class="health-grid">${checks.map(c=>`<div class="health-card ${c.ok?'ok':'warn'}"><span>${c.ok?'✓':'!'}</span><div><strong>${escapeHtml(c.label)}</strong><small>${escapeHtml(c.detail)}</small></div></div>`).join('')}</div>`;
  const errorsHtml=errors.length?`<details class="diagnostic-errors"><summary>Erreurs récentes (${errors.length})</summary><div class="stack-list">${errors.slice(0,10).map(e=>`<div class="list-row"><div><strong>${escapeHtml(e.source||'Erreur')}</strong><small>${localDateTime(e.createdAt)} · ${escapeHtml(e.message||'')}</small></div></div>`).join('')}</div></details>`:'<div class="notice info">Aucune erreur JavaScript enregistrée localement.</div>';
  modal('Santé de l’application','État du build, du stockage et des composants essentiels.',`${healthHtml}${failed}<dl class="definition-list" style="margin:14px 0"><div><dt>Build</dt><dd>${escapeHtml(BUILD_ID)}</dd></div><div><dt>Stockage persistant</dt><dd>${health.persisted?'Oui':'Non garanti'}</dd></div><div><dt>Espace utilisé</dt><dd>${formatNumber((estimate.usage||0)/1024/1024)} Mo / ${formatNumber((estimate.quota||0)/1024/1024)} Mo (${usagePct} %)</dd></div><div><dt>Pièces jointes</dt><dd>${blobs.length}</dd></div><div><dt>Sauvegardes locales</dt><dd>${backups.length}</dd></div><div><dt>Service worker</dt><dd>${reg?'Installé':'Absent'}</dd></div><div><dt>Démarrage 7.1</dt><dd>${perfRows[0]?.readyMs??'—'} ms</dd></div><div><dt>Blobs</dt><dd>${breakdown?`${formatNumber((breakdown.blobBytes||0)/1024/1024)} Mo`:'—'}</dd></div><div><dt>Sauvegardes</dt><dd>${backups.filter(b=>b.verified).length}/${backups.length} vérifiée(s)</dd></div></dl>${errorsHtml}<details><summary>Diagnostic complet</summary><pre class="diagnostic-pre">${escapeHtml(JSON.stringify(diag,null,2))}</pre></details>`,`<button class="button secondary" id="copy-diagnostic">Copier</button>${errors.length?'<button class="button secondary" id="clear-errors">Effacer erreurs</button>':''}<button class="button secondary" id="clear-cache">Nettoyer cache</button><button class="button secondary" id="force-update">Mise à jour</button><button class="button secondary" id="emergency-export">Export secours</button><button class="button danger" id="reset-runtime">Réinitialiser cache/PWA</button><button class="button primary" data-action="close-modal">Fermer</button>`,'large');
  $('#copy-diagnostic').onclick=async()=>{const copied=await copyText(JSON.stringify(diag,null,2));toast(copied?'Diagnostic copié.':'Copie impossible sur ce navigateur.',copied?'success':'error');};
  $('#emergency-export').onclick=async()=>{try{await downloadEmergencyState();toast('Export de secours téléchargé.');}catch(error){toast(error.message,'error');}};
  $('#reset-runtime').onclick=async()=>{if(!confirm('Réinitialiser le cache et le service worker ? Vos données IndexedDB seront conservées.'))return;await resetRuntimeAndReload();};
  $('#clear-errors')?.addEventListener('click',()=>{clearRecordedErrors();toast('Journal d’erreurs effacé.');openDiagnostic();});
  $('#clear-cache').onclick=async()=>{await clearAppCaches();toast('Caches applicatifs nettoyés. Rechargez la page.');};
  $('#force-update').onclick=async()=>{try{await reg?.update?.();toast('Recherche de mise à jour terminée.');}catch(error){toast(error.message,'error');}};
}

